import{I as p,o as t,c as r,b6 as e,J as o,w as d,j as i,a as l}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"نموذج الألماس المزدوج: افعل الشيء الصحيح أولاً، ثم افعل الشيء بشكل صحيح","description":"مقالة تمهيدية عن نموذج الألماس المزدوج Double Diamond للقراء بدون خبرة سابقة. فهم المراحل الأربع Discover و Define و Develop و Deliver، وتجنب الاستعجال في صنع النماذج الأولية قبل توضيح المشكلة.","frontmatter":{"title":"نموذج الألماس المزدوج: افعل الشيء الصحيح أولاً، ثم افعل الشيء بشكل صحيح","description":"مقالة تمهيدية عن نموذج الألماس المزدوج Double Diamond للقراء بدون خبرة سابقة. فهم المراحل الأربع Discover و Define و Develop و Deliver، وتجنب الاستعجال في صنع النماذج الأولية قبل توضيح المشكلة."},"headers":[],"relativePath":"ar-sa/stage-1/appendix-double-diamond/index.md","filePath":"ar-sa/stage-1/appendix-double-diamond/index.md"}'),h={name:"ar-sa/stage-1/appendix-double-diamond/index.md"},k=Object.assign(h,{setup(c){const s="حوالي <strong>1.5 ساعة</strong>";return(u,a)=>{const n=p("ChapterIntroduction");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="نموذج-الألماس-المزدوج-افعل-الشيء-الصحيح-أولاً،-ثم-افعل-الشيء-بشكل-صحيح" tabindex="-1">نموذج الألماس المزدوج: افعل الشيء الصحيح أولاً، ثم افعل الشيء بشكل صحيح <a class="header-anchor" href="#نموذج-الألماس-المزدوج-افعل-الشيء-الصحيح-أولاً،-ثم-افعل-الشيء-بشكل-صحيح" aria-label="Permalink to “نموذج الألماس المزدوج: افعل الشيء الصحيح أولاً، ثم افعل الشيء بشكل صحيح”">​</a></h1><p><a id="top-dd"></a></p><h2 id="دليل-هذا-الفصل" tabindex="-1">دليل هذا الفصل <a class="header-anchor" href="#دليل-هذا-الفصل" aria-label="Permalink to “دليل هذا الفصل”">​</a></h2>',3)),o(n,{duration:s,tags:["Double Diamond","التفكير التصميمي","تحليل المتطلبات","تصميم الحلول"],coreOutput:"تعريف مشكلة أوضح ونقطة تحقق أكثر منطقية",expectedOutput:"عدم الاستعجال في رسم النموذج الأولي، بل معرفة التفكير في المشكلة أولاً ثم مقارنة الحلول"},{default:d(()=>[...a[0]||(a[0]=[i("p",null,'العديد من الأشخاص عند صنع منتجهم الأول، الخطأ الأكثر شيوعًا ليس "عدم بذل جهد كافٍ"، بل الدخول بسرعة كبيرة في الحل.',-1),i("p",null,"بمجرد أن يظهر اتجاه في الذهن، يبدأون في التفكير في كيفية رسم الصفحة، وأين يوضع الزر، وهل يتم توصيل AI، وهل يتم عمل تسجيل دخول، وبأي أداة يتم رسم النموذج الأولي. بعد جولة كاملة من العمل، يكتشفون أن المشكلة الأساسية لم يتم التفكير فيها بوضوح: هل لدى المستخدم نقطة ألم حقيقية؟ هل هذه المشكلة تستحق الحل الآن؟ تعتقد أنك تتقدم في المشروع، لكنك في الواقع تتسارع فقط في الاتجاه الخاطئ بجدية.",-1),i("p",null,"نموذج الألماس المزدوج (Double Diamond) مصمم لتجنب هذه الحالة.",-1),i("p",null,[l("أهم تذكير قدمه هو: "),i("strong",null,'"عمل الشيء الصحيح" و"عمل الشيء بشكل صحيح" هما مرحلتان مختلفتان تمامًا.'),l(" إذا لم توضح المشكلة بعد، واستعجلت في صنع نموذج أولي، فعادةً ما ستجعل الاتجاه الخاطئ أكثر اكتمالاً فقط.")],-1)])]),_:1}),a[2]||(a[2]=e(`<div class="info custom-block"><p class="custom-block-title">الحد الأدنى من SOP</p><p><strong>الهدف</strong>: بعد القراءة، ستكون أكثر وضوحًا حول متى يجب التفكير في المشكلة أولاً ومتى يجب البدء في التفكير في الحلول والنماذج الأولية عند صنع المنتج، لتجنب العمل بجدية في الاتجاه الخاطئ منذ البداية.</p><p><strong>خطوات العمل</strong>: اتبع الخطوات الأربع <code>Discover → Define → Develop → Deliver</code>، وقم فقط بما يجب القيام به في المرحلة الحالية.</p><p><strong>النتيجة</strong>: ستحصل على تعريف مشكلة أوضح، والعديد من الحلول القابلة للمقارنة، وأصغر نسخة قابلة للتحقق.</p><p><strong>روابط سريعة</strong>: <a href="#dd-what">ما هو نموذج الألماس المزدوج</a> · <a href="#dd-first">الألماس الأول</a> · <a href="#dd-ai">كيف يساعدك AI</a></p></div><h2 id="ما-ستتعلمه-في-هذا-الفصل" tabindex="-1">ما ستتعلمه في هذا الفصل <a class="header-anchor" href="#ما-ستتعلمه-في-هذا-الفصل" aria-label="Permalink to “ما ستتعلمه في هذا الفصل”">​</a></h2><ol><li>ما هو نموذج الألماس المزدوج، ولماذا هو مناسب للمبتدئين عند صنع المنتجات</li><li>ماذا تفعل المراحل الأربع Discover و Define و Develop و Deliver على التوالي</li><li>كيف نفرق بين &quot;الآن يجب الاستمرار في التوسع&quot; و&quot;الآن يجب البدء في التضييق&quot;</li><li>كيفية استخدام نموذج الألماس المزدوج في منتجات AI وتصميم النماذج الأولية والتحقق من المتطلبات</li></ol><p><a id="dd-what"></a></p><h2 id="_1-ما-هو-نموذج-الألماس-المزدوج-بالضبط" tabindex="-1"><a href="#top-dd">1. ما هو نموذج الألماس المزدوج بالضبط</a> <a class="header-anchor" href="#_1-ما-هو-نموذج-الألماس-المزدوج-بالضبط" aria-label="Permalink to “1. ما هو نموذج الألماس المزدوج بالضبط”">​</a></h2><p>نموذج الألماس المزدوج هو إطار عمل تصميم كلاسيكي روجت له <strong>Design Council</strong> البريطانية. يرسم عملية التصميم والابتكار الكاملة في شكل ألماسين متتاليين.</p><p>السبب في كونه &quot;ألماسًا&quot; هو أن كل ألماس يحتوي على نوعين من الأفعال المتعاكسة لكنها مهمة بنفس القدر:</p><ul><li><strong>التوسع</strong>: افتح الأفق أولاً، وانظر إلى المزيد من الاحتمالات</li><li><strong>التضييق</strong>: ثم ضيق النطاق، واتخذ القرارات والتضحيات</li></ul><p>العملية الكاملة تتكون من أربع خطوات:</p><ol><li><strong>Discover</strong>: فهم واسع للمستخدمين والمشاكل والبيئة والسوق</li><li><strong>Define</strong>: استخلاص المشكلة الأساسية التي تستحق الحل حقًا من كمية كبيرة من المعلومات</li><li><strong>Develop</strong>: تطوير حلول متعددة متنوعة حول المشكلة الأساسية</li><li><strong>Deliver</strong>: الفرز، صنع النماذج الأولية، الاختبار، وتسليم الحل الأنسب</li></ol><p>إذا ضغطت هذه الخطوات الأربع في جملة واحدة أسهل في التذكر، فهي:</p><ul><li><strong>الألماس الأول</strong>: أوضح أولاً ما هي المشكلة التي يجب حلها بالضبط</li><li><strong>الألماس الثاني</strong>: ثم قرر بأي حل ستحلها</li></ul><p>وهذه هي الجملة الدقيقة التي قلتها:</p><ul><li><strong>الألماس الأول: عمل الشيء الصحيح</strong></li><li><strong>الألماس الثاني: عمل الشيء بشكل صحيح</strong></li></ul><h2 id="_2-لماذا-نموذج-الألماس-المزدوج-مناسب-بشكل-خاص-للمبتدئين" tabindex="-1">2. لماذا نموذج الألماس المزدوج مناسب بشكل خاص للمبتدئين <a class="header-anchor" href="#_2-لماذا-نموذج-الألماس-المزدوج-مناسب-بشكل-خاص-للمبتدئين" aria-label="Permalink to “2. لماذا نموذج الألماس المزدوج مناسب بشكل خاص للمبتدئين”">​</a></h2><p>الإيقاع الأكثر شيوعًا بين المبتدئين عند صنع المنتجات غالبًا ما يكون هكذا:</p><ul><li>التفكير في فكرة</li><li>الشعور بأن هذا الاتجاه رائع</li><li>البدء فورًا في رسم النموذج الأولي</li><li>أثناء العمل، اكتشاف أن الوظائف تزداد أكثر فأكثر</li><li>في النهاية، عدم المعرفة ما هي المشكلة التي يتم حلها بالضبط</li></ul><p>قيمة نموذج الألماس المزدوج ليست في جعل العملية معقدة، بل في <strong>إجبارك على فصل &quot;فهم المشكلة&quot; و&quot;تصميم الحل&quot;</strong>.</p><p>هذا الأمر يبدو عاديًا، لكنه مهم جدًا في الواقع. لأن العديد من المنتجات الفاشلة لم تفشل لأن التنفيذ لم يكن جادًا، بل لأن:</p><ul><li>تم اختيار المشكلة الخاطئة</li><li>تم سوء فهم المستخدم</li><li>تم تثبيت الحل مبكرًا جدًا</li><li>تم إنفاق الكثير من الوقت في صقل التفاصيل، دون التحقق من الاتجاه</li></ul><p>نموذج الألماس المزدوج يذكرك باستمرار:</p><ul><li>لا تفترض أن المشكلة ثابتة لمجرد أن الفكرة مريحة</li><li>لا تفترض أن الحل يستحق التنفيذ لمجرد أنه يمكن صنعه</li><li>لا تفترض أن المستخدم سيحتاجه حقًا لمجرد أن النموذج الأولي يبدو كاملًا</li></ul><p><a id="dd-first"></a></p><h2 id="_3-الألماس-الأول-عمل-الشيء-الصحيح" tabindex="-1"><a href="#top-dd">3. الألماس الأول: عمل الشيء الصحيح</a> <a class="header-anchor" href="#_3-الألماس-الأول-عمل-الشيء-الصحيح" aria-label="Permalink to “3. الألماس الأول: عمل الشيء الصحيح”">​</a></h2><p>الألماس الأول يركز على <strong>المشكلة نفسها</strong>، وليس الحل.</p><p>يمكنك فهمه كجملة واحدة: <strong>لا تستعجل في العمل، أوضح أولاً ما إذا كان يستحق العمل أم لا.</strong></p><h3 id="_3-1-discover-افتح-مساحة-المشكلة-أولاً" tabindex="-1">3.1 Discover: افتح مساحة المشكلة أولاً <a class="header-anchor" href="#_3-1-discover-افتح-مساحة-المشكلة-أولاً" aria-label="Permalink to “3.1 Discover: افتح مساحة المشكلة أولاً”">​</a></h3><p>المهمة الأساسية لمرحلة Discover هي <strong>البحث الواسع، وليس الاستنتاج السريع</strong>.</p><p>ما يتم فعله عادةً في هذه الخطوة يشمل:</p><ul><li>مشاهدة كيف يعمل المستخدمون في السيناريوهات الحقيقية</li><li>مقابلة المستخدمين المحتملين، ومعرفة متى واجهوا المشكلة آخر مرة</li><li>مراقبة كيف يتدبرون الأمر حاليًا</li><li>النظر إلى كيفية تعامل المنافسين والبدائل</li><li>جمع معلومات السوق والعمليات والقيود وسلسلة القيمة</li></ul><p>العديد من الأشخاص يخطئون في الاعتقاد بأن Discover هو مجرد &quot;مشاهدة المزيد من المعلومات&quot;. لكن الأهم هو: <strong>تحتاج إلى فهم الأشخاص والسيناريوهات، وليس فقط البحث عن كومة من المعلومات.</strong></p><p>مثلاً، إذا كنت تريد صنع أداة &quot;AI يساعد في تنظيم محاضر الاجتماعات&quot;، ففي مرحلة Discover يجب أن تركز أكثر على:</p><ul><li>أين يكون المستخدم في أكثر ألم بعد الاجتماع</li><li>هل الصعوبة في التدوين، أم في التنظيم، أم في المشاركة</li><li>هل يكتبون بأنفسهم، أم يجعلون المتدربين يكتبون، أم يستمعون للتسجيل مرة أخرى، أم لا ينظمون أبدًا</li><li>أي سيناريوهات الاجتماعات تحتاج أكثر لمحاضر، وأيها لا تحتاج أبدًا</li></ul><p>الهدف الأهم في هذه الخطوة ليس الوصول إلى إجابة، بل <strong>لا تعتقد أنك تعرف الإجابة مبكرًا جدًا.</strong></p><h3 id="_3-2-define-استخلص-المشكلة-الأساسية-من-كومة-المعلومات" tabindex="-1">3.2 Define: استخلص المشكلة الأساسية من كومة المعلومات <a class="header-anchor" href="#_3-2-define-استخلص-المشكلة-الأساسية-من-كومة-المعلومات" aria-label="Permalink to “3.2 Define: استخلص المشكلة الأساسية من كومة المعلومات”">​</a></h3><p>إذا كان Discover هو فتح الأفق، فإن Define هو بدء التضييق.</p><p>ما يجب فعله في مرحلة Define ليس الاحتفاظ بكل الملاحظات، بل السؤال:</p><ul><li>أي مشكلة هي الأكثر استحقاقًا للحل أولاً</li><li>أي مشكلة هي الأكثر تكرارًا والأكثر ألمًا والأكثر قيمة</li><li>أي سيناريو سنستهدفه فقط في النسخة الأولى</li></ul><p>جوهر هذه الخطوة هو تحويل موضوع واسع إلى تعريف مشكلة واضح.</p><p>مثلاً، في البداية قد تقول:</p><blockquote><p>أريد صنع أداة AI لتحسين كفاءة الاجتماعات.</p></blockquote><p>في مرحلة Define، قد يصبح التعبير الأفضل:</p><blockquote><p>سنحل أولاً مشكلة عدم قدرة فرق المشاريع على إخراج محضر يتضمن المهام والمسؤولين والمواعيد النهائية في غضون 10 دقائق بعد اجتماعات التعاون التي تستمر من 30 إلى 60 دقيقة.</p></blockquote><p>هنا تبدأ المشكلة في الوضوح:</p><ul><li>من هو المستخدم</li><li>ما هو السيناريو</li><li>ما هو العائق</li><li>ما هو معيار النجاح</li></ul><p>جوهر Define هو <strong>التضييق من &quot;مشاكل كثيرة&quot; إلى &quot;أي مشكلة سنحلها أولاً هذه المرة&quot;.</strong></p><h2 id="_4-الألماس-الثاني-عمل-الشيء-بشكل-صحيح" tabindex="-1">4. الألماس الثاني: عمل الشيء بشكل صحيح <a class="header-anchor" href="#_4-الألماس-الثاني-عمل-الشيء-بشكل-صحيح" aria-label="Permalink to “4. الألماس الثاني: عمل الشيء بشكل صحيح”">​</a></h2><p>عندما تكمل الألماس الأول، حينها فقط تكون مناسبًا حقًا للدخول في الألماس الثاني. لأنك في هذه اللحظة لا تحل اتجاهًا غامضًا، بل مشكلة محددة تم تضييقها.</p><h3 id="_4-1-develop-تطوير-حلول-متنوعة-حول-المشكلة-الأساسية" tabindex="-1">4.1 Develop: تطوير حلول متنوعة حول المشكلة الأساسية <a class="header-anchor" href="#_4-1-develop-تطوير-حلول-متنوعة-حول-المشكلة-الأساسية" aria-label="Permalink to “4.1 Develop: تطوير حلول متنوعة حول المشكلة الأساسية”">​</a></h3><p>تركيز مرحلة Develop هو <strong>استكشاف حلول محتملة متعددة حول نفس المشكلة</strong>.</p><p>لاحظ أن التوسع هنا يختلف عن مرحلة Discover.</p><ul><li>توسع Discover هو استكشاف مساحة المشكلة</li><li>توسع Develop هو استكشاف مساحة الحلول</li></ul><p>بالعودة إلى مثال محاضر الاجتماعات، في مرحلة Develop، يمكنك البدء في التفكير:</p><ul><li>هل نصنع أداة ويب أم إضافة للاجتماعات</li><li>هل نعالج بعد رفع التسجيل أم نسجل في الوقت الفعلي</li><li>هل نعمل ملخص فقط أم نركز على استخراج المهام</li><li>هل نؤكد على الكفاءة الشخصية أم على مزامنة الفريق</li><li>هل نعطي المستخدم حرية التعديل أم نخرج قالبًا منظمًا مباشرة</li></ul><p>هذه الخطوة مناسبة جدًا للعصف الذهني، ومناسبة جدًا أيضًا للعمل مع الفريق لفتح الحلول.</p><p>لكن هناك شرط مسبق: <strong>جميع الحلول يجب أن تخدم نفس المشكلة المحددة.</strong> إذا لم يتم تعريف المشكلة بوضوح، فمن السهل أن يتحول Develop مرة أخرى إلى فوضى في الوظائف.</p><h3 id="_4-2-deliver-اختيار-الحل،-صنع-النموذج-الأولي،-الاختبار-والتسليم" tabindex="-1">4.2 Deliver: اختيار الحل، صنع النموذج الأولي، الاختبار والتسليم <a class="header-anchor" href="#_4-2-deliver-اختيار-الحل،-صنع-النموذج-الأولي،-الاختبار-والتسليم" aria-label="Permalink to “4.2 Deliver: اختيار الحل، صنع النموذج الأولي، الاختبار والتسليم”">​</a></h3><p>مرحلة Deliver هي مرحلة التضييق في الألماس الثاني.</p><p>ما يجب عليك فعله هنا ليس الاستمرار في التفكير في المزيد، بل بدء الحكم:</p><ul><li>أي حل هو الأنسب للمرحلة الحالية</li><li>أي نسخة هي الأصغر لكنها الأكثر فائدة</li><li>أي الوظائف يجب تنفيذها أولاً وأيها يمكن تأجيله</li><li>كيفية صنع نموذج أولي واختباره والتحقق منه على نطاق صغير</li></ul><p>العديد من الأشخاص يعتقدون أن Deliver يعني &quot;الإطلاق&quot;. في الواقع معناه الأكثر دقة هو: <strong>تحويل حل إلى شيء قابل للاختبار والتحقق والتكرار.</strong></p><p>قد يكون:</p><ul><li>مخطط تدفق منخفض الدقة</li><li>نموذج أولي Figma</li><li>MVP قابل للتشغيل</li><li>اختبار مستخدمين على نطاق صغير</li><li>نسخة مكررة بعد تغذية راجعة حقيقية</li></ul><p>تركيز Deliver ليس &quot;التسليم المثالي&quot;، بل <strong>وضع الحل في بيئة حقيقية للتحقق في أسرع وقت ممكن.</strong></p><h2 id="_5-جدول-مقارنة-سهل-التذكر" tabindex="-1">5. جدول مقارنة سهل التذكر <a class="header-anchor" href="#_5-جدول-مقارنة-سهل-التذكر" aria-label="Permalink to “5. جدول مقارنة سهل التذكر”">​</a></h2><p>إذا كنت دائمًا تخلط بين المراحل الأربع، يمكنك حفظ هذا الإصدار مباشرة:</p><table tabindex="0"><thead><tr><th>المرحلة</th><th>ماذا تفعل</th><th>الكلمات المفتاحية</th><th>المخرجات الشائعة</th></tr></thead><tbody><tr><td>Discover</td><td>فهم المشكلة</td><td>بحث، مراقبة، مقابلات، جمع معلومات</td><td>رؤى المستخدمين، ملاحظات السيناريوهات، قائمة المشاكل</td></tr><tr><td>Define</td><td>تعريف المشكلة</td><td>استخلاص، تركيز، تضحيات، إعادة صياغة المشكلة</td><td>تعريف المشكلة، الأولويات، نقطة دخول MVP</td></tr><tr><td>Develop</td><td>استكشاف الحلول</td><td>عصف ذهني، مقارنة، إبداع مشترك، تصور النماذج الأولية</td><td>قائمة الحلول، مخططات التدفق، اتجاهات النماذج الأولية</td></tr><tr><td>Deliver</td><td>التحقق من الحلول</td><td>نموذج أولي، اختبار، تكرار، تسليم</td><td>نموذج أولي، تغذية راجعة من الاختبار، نسخة محسنة</td></tr></tbody></table><p>وإذا ضغطنا أكثر، فهذا هو الشكل:</p><ul><li><strong>Discover / Define</strong>: حل &quot;عمل الشيء الصحيح&quot;</li><li><strong>Develop / Deliver</strong>: حل &quot;عمل الشيء بشكل صحيح&quot;</li></ul><h2 id="_6-أخطاء-نموذج-الألماس-المزدوج-الأكثر-شيوعًا" tabindex="-1">6. أخطاء نموذج الألماس المزدوج الأكثر شيوعًا <a class="header-anchor" href="#_6-أخطاء-نموذج-الألماس-المزدوج-الأكثر-شيوعًا" aria-label="Permalink to “6. أخطاء نموذج الألماس المزدوج الأكثر شيوعًا”">​</a></h2><h3 id="_6-1-discover-لم-يكتمل-بعد،-وتم-الانتقال-مباشرة-إلى-deliver" tabindex="-1">6.1 Discover لم يكتمل بعد، وتم الانتقال مباشرة إلى Deliver <a class="header-anchor" href="#_6-1-discover-لم-يكتمل-بعد،-وتم-الانتقال-مباشرة-إلى-deliver" aria-label="Permalink to “6.1 Discover لم يكتمل بعد، وتم الانتقال مباشرة إلى Deliver”">​</a></h3><p>هذا هو الأكثر شيوعًا. العديد من الأشخاص بمجرد أن تكون لديهم فكرة يبدأون في رسم النماذج الأولية وكتابة PRD وتوصيل النماذج وصنع الصفحات.</p><p>المشكلة ليست أنك لا تعمل بجدية، بل أنك ربما لم تؤكد بعد ما إذا كانت المشكلة تستحق الحل.</p><h3 id="_6-2-discover-لفترة-طويلة،-لكن-define-لا-يحدث-أبدًا" tabindex="-1">6.2 Discover لفترة طويلة، لكن Define لا يحدث أبدًا <a class="header-anchor" href="#_6-2-discover-لفترة-طويلة،-لكن-define-لا-يحدث-أبدًا" aria-label="Permalink to “6.2 Discover لفترة طويلة، لكن Define لا يحدث أبدًا”">​</a></h3><p>النوع الآخر من المتطرفين هو البحث المستمر، والاطلاع المستمر على المواد، والمقابلات المستمرة، لكن عدم الجراءة على التضييق.</p><p>الألماس المزدوج ليس لجعلك تتوسع إلى ما لا نهاية، بل لتذكيرك: بعد التوسع يجب الدخول في الحكم والتضحيات.</p><h3 id="_6-3-بعد-define،-يتم-تعديل-المشكلة-سرًا" tabindex="-1">6.3 بعد Define، يتم تعديل المشكلة سرًا <a class="header-anchor" href="#_6-3-بعد-define،-يتم-تعديل-المشكلة-سرًا" aria-label="Permalink to “6.3 بعد Define، يتم تعديل المشكلة سرًا”">​</a></h3><p>العديد من الفرق في مرحلة Develop، بسبب سهولة حل معين، تقوم بتعديل تعريف المشكلة بشكل عكسي ليتوافق مع الحل الموجود.</p><p>هذا خطير جدًا. لأنك ربما لا تحل المشكلة، بل تبحث عن مبرر للحل الذي تفضله.</p><h3 id="_6-4-سوء-فهم-deliver-على-أنه-إطلاق-شامل" tabindex="-1">6.4 سوء فهم Deliver على أنه &quot;إطلاق شامل&quot; <a class="header-anchor" href="#_6-4-سوء-فهم-deliver-على-أنه-إطلاق-شامل" aria-label="Permalink to “6.4 سوء فهم Deliver على أنه &quot;إطلاق شامل&quot;”">​</a></h3><p>Deliver لا يعني أنه لا يُعد منتهيًا إلا بعد إكمال المنتج بالكامل. في كثير من الأحيان، نموذج أولي قابل للاختبار، أو جولة تجريب مستخدمين حقيقيين، هي بالفعل deliver جيد.</p><h2 id="_7-في-منتجات-ai،-كيفية-استخدام-نموذج-الألماس-المزدوج" tabindex="-1">7. في منتجات AI، كيفية استخدام نموذج الألماس المزدوج <a class="header-anchor" href="#_7-في-منتجات-ai،-كيفية-استخدام-نموذج-الألماس-المزدوج" aria-label="Permalink to “7. في منتجات AI، كيفية استخدام نموذج الألماس المزدوج”">​</a></h2><p>منتجات AI عرضة بشكل خاص للوقوع في فخ &quot;القدرات أولاً&quot;، لأن قدرات النموذج تبدو مغرية جدًا. ستشعر برغبة قوية في التفكير مباشرة:</p><ul><li>هل يتم توصيل الوسائط المتعددة</li><li>هل يتم عمل Agent</li><li>هل يتم إضافة سير عمل</li><li>هل يتم توصيل الصوت والصور والبحث عبر الإنترنت</li></ul><p>لكن نموذج الألماس المزدوج سيجبرك على السؤال أولاً:</p><ul><li>أين يعلق المستخدم حقًا</li><li>هل هذه النقطة العائقية تتطلب AI حتمًا</li><li>إذا لم يتم استخدام AI، فأين أسوأ جزء في الطريقة الحالية</li><li>بعد إضافة AI، ما هو التقدم الأساسي</li></ul><p>هذا يساعدك في تجنب حالة شائعة: <strong>قدرات قوية جدًا، لكن القيمة ضعيفة جدًا.</strong></p><p>ترتيب عملي هو:</p><ol><li>في مرحلة Discover، راقب كيف يتعامل المستخدمون مع المهام حاليًا</li><li>في مرحلة Define، اكتب السيناريو الأكثر ألمًا كتعريف مشكلة واضح</li><li>في مرحلة Develop، قارن أي قدرات AI هي الأنسب لخدمة هذه المشكلة</li><li>في مرحلة Deliver، اصنع أصغر نسخة ودع المستخدمين الحقيقيين يختبرونها</li></ol><h2 id="_8-قالب-ألماس-مزدوج-يمكن-استخدامه-مباشرة" tabindex="-1">8. قالب ألماس مزدوج يمكن استخدامه مباشرة <a class="header-anchor" href="#_8-قالب-ألماس-مزدوج-يمكن-استخدامه-مباشرة" aria-label="Permalink to “8. قالب ألماس مزدوج يمكن استخدامه مباشرة”">​</a></h2><p>إذا كنت تصنع منتجك الخاص، يمكنك البدء بالكتابة وفقًا لهذا الترتيب:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>من هم المستخدمون الذين لاحظتهم؟</li><li>متى واجهوا هذه المشكلة آخر مرة؟</li><li>كيف يحلونها حاليًا؟</li><li>أين يكون أكثر ما يزعجهم وأبطأهم وأقل ما يطمئنهم؟</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>من بين هذه المشاكل، أيها الأكثر استحقاقًا للحل أولاً؟</li><li>أي سيناريو هو الأكثر تكرارًا أو الأكثر أهمية؟</li><li>من سنخدم في النسخة الأولى فقط، وماذا سنحل فقط؟</li><li>بعد الحل الناجح، ماذا سيتغير في حالة المستخدم؟</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>بالنسبة لهذه المشكلة، ما هي الحلول المحتملة؟</li><li>أي الحلول هي الأخف والأسرع والأسهل للتحقق؟</li><li>أيها يجب عمله، وأيها يمكن تأجيله؟</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>ما هو أصغر شيء يمكننا تسليمه للتحقق من هذا الاتجاه؟</li><li>هل هو مخطط تدفق، أم نموذج أولي، أم MVP؟</li><li>من نحتاج لاختباره؟</li><li>بعد الاختبار، كيف نحكم على ما إذا كنا سنستمر أم نعدل أم نتخلى؟</li></ul><h2 id="_9-مثال-يمكن-فهمه-حتى-من-المبتدئين-تمامًا" tabindex="-1">9. مثال يمكن فهمه حتى من المبتدئين تمامًا <a class="header-anchor" href="#_9-مثال-يمكن-فهمه-حتى-من-المبتدئين-تمامًا" aria-label="Permalink to “9. مثال يمكن فهمه حتى من المبتدئين تمامًا”">​</a></h2><p>لنفترض أنك تريد صنع أداة AI &quot;تساعد طلاب الجامعات في إعداد سيرهم الذاتية للبحث عن عمل&quot;.</p><p>العديد من الأشخاص في البداية سيدخلون مباشرة في الألماس الثاني، ويبدأون في التفكير:</p><ul><li>هل يتم تجميل تلقائي بنقرة واحدة</li><li>هل يتم إعادة كتابة ذكية</li><li>هل يتم مطابقة تلقائية مع وصف الوظيفة</li><li>هل يتم توليد مقدمة ذاتية</li></ul><p>لكن وفقًا لنموذج الألماس المزدوج، العملية الأفضل ستكون:</p><h3 id="الألماس-الأول" tabindex="-1">الألماس الأول <a class="header-anchor" href="#الألماس-الأول" aria-label="Permalink to “الألماس الأول”">​</a></h3><p><strong>Discover</strong></p><ul><li>تحدث مع الخريجين الجدد عن متى عدلوا سيرتهم الذاتية آخر مرة</li><li>انظر كيف يحولون سيرتهم القديمة إلى نسخة جديدة</li><li>افهم ما يزعجهم أكثر: &quot;لا أعرف كيف أكتب&quot; أم &quot;لا أعرف كيف أعدل&quot; أم &quot;لا أعرف كيف أحكم على جودتها&quot;</li></ul><p><strong>Define</strong></p><ul><li>أخيرًا تضيق إلى مشكلة أكثر تحديدًا:</li><li>ليس &quot;طلاب الجامعات لا يعرفون كيف يصنعون سيرة ذاتية&quot;</li><li>بل &quot;الطالب الذي يقدم على تدريب لأول مرة، يجد صعوبة في تحويل خبراته السابقة إلى تعبيرات تتناسب مع الوظيفة، ولذلك يؤخر التقديم&quot;</li></ul><h3 id="الألماس-الثاني" tabindex="-1">الألماس الثاني <a class="header-anchor" href="#الألماس-الثاني" aria-label="Permalink to “الألماس الثاني”">​</a></h3><p><strong>Develop</strong></p><ul><li>فكر في عدة حلول: مكتبة قوالب، إعادة كتابة AI، مقارنة مع الوظيفة، تقييم السيرة الذاتية، مراجع حالات</li></ul><p><strong>Deliver</strong></p><ul><li>النسخة الأولى فقط &quot;إعادة كتابة نقاط الخبرة بناءً على وصف الوظيفة&quot;</li><li>جربها مع 5 طلاب، وانظر ما إذا كانوا سيقدمون النسخة الأولى من سيرتهم الذاتية بشكل أسرع</li></ul><p>ستكتشف أنه بمجرد أن يتم تنفيذ الألماس الأول بشكل متين، سيكون الألماس الثاني أوضح بكثير.</p><h2 id="_10-ملخص" tabindex="-1">10. ملخص <a class="header-anchor" href="#_10-ملخص" aria-label="Permalink to “10. ملخص”">​</a></h2><p>أقوى جانب في نموذج الألماس المزدوج هو أنه يساعدك في تقسيم كتلة الفوضى الكاملة إلى أربع حركات أوضح:</p><ul><li>توسع أولاً لفهم المشكلة</li><li>ثم ضيق لتعريف المشكلة</li><li>ثم توسع لاستكشاف الحلول</li><li>وأخيرًا ضيق لتسليم الحل</li></ul><p>إنه لا يجعلك أبطأ، بل يجعلك <strong>توفر الكثير من المسارات التي تبدو مشغولة لكنها في الاتجاه الخاطئ.</strong></p><p>خاصة في عصر AI، حيث أصبح صنع الأشياء أسرع فأسرع، يصبح نموذج الألماس المزدوج أكثر أهمية. لأنه عندما يصبح &quot;الصنع&quot; أسهل فأسهل، ستكون القدرة النادرة حقًا هي: <strong>هل تحل مشكلة تستحق الحل، وهل تستخدم الطريقة المناسبة لحلها.</strong></p><p>تذكر هذه الجملة فقط:</p><p><strong>افعل الشيء الصحيح أولاً، ثم افعل الشيء بشكل صحيح.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-كيفية-استخدام-ai-لمساعدتك-في-تشغيل-عملية-الألماس-المزدوج" tabindex="-1"><a href="#top-dd">11. كيفية استخدام AI لمساعدتك في تشغيل عملية الألماس المزدوج</a> <a class="header-anchor" href="#_11-كيفية-استخدام-ai-لمساعدتك-في-تشغيل-عملية-الألماس-المزدوج" aria-label="Permalink to “11. كيفية استخدام AI لمساعدتك في تشغيل عملية الألماس المزدوج”">​</a></h2><p>نموذج الألماس المزدوج نفسه ليس أداة AI، لكن AI مناسب جدًا ليكون &quot;مسرعًا&quot; في المراحل الأربع. المفتاح ليس جعل AI يتخذ القرارات بدلاً منك، بل جعله يساعدك في توسيع الأفق وتنظيم المعلومات ومقارنة الحلول وتوليد مواد التحقق.</p><h3 id="_11-1-في-مرحلة-discover،-استخدم-ai-للقيام-بجولة-تمهيدية-للمعلومات" tabindex="-1">11.1 في مرحلة Discover، استخدم AI للقيام بجولة تمهيدية للمعلومات <a class="header-anchor" href="#_11-1-في-مرحلة-discover،-استخدم-ai-للقيام-بجولة-تمهيدية-للمعلومات" aria-label="Permalink to “11.1 في مرحلة Discover، استخدم AI للقيام بجولة تمهيدية للمعلومات”">​</a></h3><p>قبل المقابلات والبحث الرسمي، يمكنك جعل AI يساعدك في عمل مسح خفيف للمشاكل، مثلاً:</p><ul><li>ما هي البدائل الشائعة في السوق</li><li>عما يشكو المستخدمون أكثر في المجتمعات العامة</li><li>في أي سيناريوهات ومجموعات تظهر هذه المشكلة عادةً</li><li>ما الذي تتجاهله المنتجات الحالية عادةً</li></ul><p>هذه الخطوة لا يمكنها استبدال البحث الحقيقي، لكنها مناسبة جدًا لمساعدتك في بناء خريطة مشاكل بسرعة.</p><p>إدخال بسيط للمبتدئين يمكن أن يكون:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد صنع أداة تساعد طلاب الجامعات في تعديل سيرهم الذاتية.</span></span>
<span class="line"><span>لا تساعدني في التفكير في الوظائف أولاً، بل ساعدني في رؤية ما هي المشاكل الأكثر شيوعًا التي يواجهها الناس في هذه المسألة.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>خريطة المشاكل الأولية:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. لا أعرف ما هي الخبرات التي يجب كتابتها</span></span>
<span class="line"><span>2. لا أعرف كيف أعدل لتناسب الوظيفة</span></span>
<span class="line"><span>3. عدلت عدة نسخ لكنني لا أزال غير متأكد مما إذا كانت جيدة بما فيه الكفاية</span></span>
<span class="line"><span>4. أحتاج شخصًا يراجع لي، لكن من المحرج أن أزعج الآخرين في كل مرة</span></span>
<span class="line"><span>5. بسبب عدم اليقين، أؤخر التقديم دائمًا</span></span></code></pre></div><p>هدف هذا النوع من المخرجات ليس أن يستنتج بدلاً منك، بل أن يساعدك في الدخول إلى Discover بشكل أسرع.</p><h3 id="_11-2-في-مرحلة-define،-دع-ai-يساعدك-في-تضييق-تعريف-المشكلة" tabindex="-1">11.2 في مرحلة Define، دع AI يساعدك في تضييق تعريف المشكلة <a class="header-anchor" href="#_11-2-في-مرحلة-define،-دع-ai-يساعدك-في-تضييق-تعريف-المشكلة" aria-label="Permalink to “11.2 في مرحلة Define، دع AI يساعدك في تضييق تعريف المشكلة”">​</a></h3><p>العديد من الأشخاص بعد جمع كومة من المواد، أصعب شيء هو ضغط المشكلة في جملة واحدة واضحة حقًا. يمكنك تسليم ملاحظات البحث إلى AI وجعله يساعدك في ضغطها في عدة تعريفات مشاكل مرشحة:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>فيما يلي ملاحظات البحث وتغذية المستخدمين التي جمعتها في مرحلة Discover:</span></span>
<span class="line"><span>[ألصق المحتوى]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ساعدني في ثلاثة أشياء:</span></span>
<span class="line"><span>1. تلخيص أنماط المشاكل الأكثر تكرارًا</span></span>
<span class="line"><span>2. ترتيب 3 مشاكل تستحق الحل أولاً حسب تكرار المشكلة وشدة الألم وقابلية التحقق</span></span>
<span class="line"><span>3. اكتب كل مشكلة كتعريف مشكلة محدد في جملة واحدة</span></span></code></pre></div><p>هذا سيساعدك على الدخول إلى Define بشكل أسهل، بدلاً من البقاء في حالة &quot;المشاكل كثيرة&quot;.</p><p>يمكنك حتى كتابة الإدخال ببساطة شديدة:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>المشاكل التي جمعتها حاليًا هي:</span></span>
<span class="line"><span>1. الجميع لا يعرف ماذا يكتب في السيرة الذاتية</span></span>
<span class="line"><span>2. الجميع لا يعرف كيف يعدل</span></span>
<span class="line"><span>3. الجميع يشعر دائمًا بأنه لم يعدل بشكل جيد ويخاف من التقديم</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ساعدني في رؤية أي مشكلة أنسب للحل أولاً في النسخة الأولى.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>المشكلة المقترح حلها أولاً:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;الطالب الذي يقدم على تدريب لأول مرة، غير متأكد مما إذا كانت سيرته الذاتية قد وصلت إلى مستوى قابل للتقديم، ولذلك يعدلها مرارًا ويؤخر التقديم.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>الأسباب:</span></span>
<span class="line"><span>1. هذه المشكلة أكثر تحديدًا</span></span>
<span class="line"><span>2. يمكنها تفسير سلوك التأجيل</span></span>
<span class="line"><span>3. أسهل في تصميم نسخة صغيرة للتحقق</span></span></code></pre></div><p>هذا النوع من المخرجات مفيد جدًا، لأنه يساعدك على التضييق من كومة مشاكل غامضة إلى تعريف أقرب إلى نقطة بداية MVP.</p><h3 id="_11-3-في-مرحلة-develop،-استخدم-ai-لتوسيع-حلول-متعددة" tabindex="-1">11.3 في مرحلة Develop، استخدم AI لتوسيع حلول متعددة <a class="header-anchor" href="#_11-3-في-مرحلة-develop،-استخدم-ai-لتوسيع-حلول-متعددة" aria-label="Permalink to “11.3 في مرحلة Develop، استخدم AI لتوسيع حلول متعددة”">​</a></h3><p>العديد من الأشخاص بمجرد تعريف المشكلة، يركزون فقط على الحل الأول الذي يتبادر إلى الذهن. AI مناسب جدًا في هذه الخطوة لمساعدتك في التوسيع الإجباري:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>لقد عرفت المشكلة الأساسية: [تعريف مشكلتك]</span></span>
<span class="line"><span>لا تعطيني إجابة نهائية مباشرة، بل اقترح 2-3 اتجاهات حل من كل من الزوايا التالية:</span></span>
<span class="line"><span>1. MVP الأخف</span></span>
<span class="line"><span>2. الحل الأنسب للتحقق من الطلب</span></span>
<span class="line"><span>3. الحل الأنسب لتحسين التجربة</span></span>
<span class="line"><span>4. حل لا يعتمد على AI</span></span>
<span class="line"><span>5. حل يعتمد على AI</span></span>
<span class="line"><span>أخيرًا قارن مزايا ومخاطر وتكلفة التحقق لكل حل.</span></span></code></pre></div><p>بهذه الطريقة لن تكون مقيدًا بحل واحد في مرحلة مبكرة جدًا.</p><p>يمكنك كتابة إدخال بسيط:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>تعريف مشكلتي الحالي هو:</span></span>
<span class="line"><span>&quot;طالب الجامعة غير متأكد مما إذا كانت سيرته الذاتية يمكن تقديمها، ولذلك يؤخر التقديم دائمًا.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ساعدني في التفكير في 4 حلول مختلفة، لا تعطيني واحدًا فقط.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>الحل 1: قائمة تحقق لقابلية تقديم السيرة الذاتية</span></span>
<span class="line"><span>الحل 2: إعادة كتابة مستهدفة بناءً على وصف الوظيفة</span></span>
<span class="line"><span>الحل 3: تقديم تحذيرات المخاطر بعد أن يحمل المستخدم سيرته الذاتية</span></span>
<span class="line"><span>الحل 4: تقديم مقارنة مع حالات ممتازة لمساعدة المستخدم في تقييم الفجوة</span></span></code></pre></div><p>هذا يجعل من الأسهل الدخول في &quot;مقارنة الحلول&quot; بدلاً من التركيز فقط على اتجاه إعادة كتابة AI منذ البداية.</p><h3 id="_11-4-في-مرحلة-deliver،-استخدم-ai-لتوليد-نصوص-النماذج-الأولية-ومواد-الاختبار" tabindex="-1">11.4 في مرحلة Deliver، استخدم AI لتوليد نصوص النماذج الأولية ومواد الاختبار <a class="header-anchor" href="#_11-4-في-مرحلة-deliver،-استخدم-ai-لتوليد-نصوص-النماذج-الأولية-ومواد-الاختبار" aria-label="Permalink to “11.4 في مرحلة Deliver، استخدم AI لتوليد نصوص النماذج الأولية ومواد الاختبار”">​</a></h3><p>عندما تدخل مرحلة Deliver، AI مناسب جدًا لتسريع هذه الأعمال:</p><ul><li>توليد نصوص الصفحات في النماذج الأولية منخفضة الدقة</li><li>تنظيم سكريبت اختبار المستخدمين</li><li>توليد عدة إصدارات قابلة للمقارنة من العناوين والأزرار والتعليمات</li><li>تنظيم التغذية الراجعة وقائمة المشاكل بعد الاختبار</li></ul><p>مثلاً، يمكنك جعل AI يساعدك في توليد سكريبت اختبار مستخدمين لمدة 20 دقيقة، أو مساعدتك في تنظيم تغذية 5 مستخدمين راجعة إلى أساس حكم &quot;استمر / عدل الاتجاه / توقف&quot;.</p><p>إدخال بسيط يمكن أن يكون:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>صنعت نموذجًا أوليًا بسيطًا جدًا:</span></span>
<span class="line"><span>المستخدم يحمل سيرته الذاتية، والنظام يخبره بأي الأماكن لا تزال غير مناسبة للتقديم.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ساعدني في توليد سكريبت اختبار مستخدمين لمدة 15 دقيقة.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>سكريبت اختبار 15 دقيقة:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. اطلب من المستخدم أولًا وصف تجربة تقديم السيرة الذاتية الأخيرة</span></span>
<span class="line"><span>2. دع المستخدم يكمل تحميل السيرة الذاتية بشكل مستقل</span></span>
<span class="line"><span>3. راقب ما إذا كان يفهم نتائج التغذية الراجعة</span></span>
<span class="line"><span>4. اسأل: أي من هذه التلميحات كانت الأكثر فائدة، وأيها أربكك</span></span>
<span class="line"><span>5. اسأل: قبل التقديم المرة القادمة، هل تريد استخدامه مرة أخرى</span></span></code></pre></div><p>هذا النوع من المخرجات عملي جدًا، لأنه يساعدك على الانتقال من &quot;أنهيت النموذج الأولي&quot; إلى &quot;كيف أختبر بعد ذلك&quot;.</p><h3 id="_11-5-دع-ai-يلعب-دور-حارس-المرحلة" tabindex="-1">11.5 دع AI يلعب دور &quot;حارس المرحلة&quot; <a class="header-anchor" href="#_11-5-دع-ai-يلعب-دور-حارس-المرحلة" aria-label="Permalink to “11.5 دع AI يلعب دور &quot;حارس المرحلة&quot;”">​</a></h3><p>أكثر المشاكل شيوعًا في نموذج الألماس المزدوج هو أن الأشخاص يتخطون المراحل. يمكنك جعل AI مباشرة يعمل كحارس، يذكرك في أي مرحلة أنت بالضبط:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>العب دور مدرب عملية المنتج.</span></span>
<span class="line"><span>فيما يلي حالة مشروعي الحالية: [وصفك]</span></span>
<span class="line"><span>احكم على ما إذا كنت أشبه بالوجود في Discover أم Define أم Develop أم Deliver.</span></span>
<span class="line"><span>وأخبرني:</span></span>
<span class="line"><span>1. هل قفزت مبكرًا جدًا إلى المرحلة التالية</span></span>
<span class="line"><span>2. ما هو الإجراء الأكثر أهمية الذي يجب إكماله في المرحلة الحالية</span></span>
<span class="line"><span>3. أي الأشياء يجب ألا أفعلها الآن</span></span></code></pre></div><p>هذا مفيد جدًا للمبتدئين، لأنك تتسرع بسهولة في &quot;رسم النموذج الأولي قبل أن توضح المشكلة&quot;.</p><h2 id="📚-الواجبات" tabindex="-1">📚 الواجبات <a class="header-anchor" href="#📚-الواجبات" aria-label="Permalink to “📚 الواجبات”">​</a></h2><p>يرجى إكمال الواجبات التالية بناءً على المحتوى أعلاه:</p><ol><li>اختر فكرة منتج تريد صنعها مؤخرًا، واكتب مسودتها في أربع خطوات Discover و Define و Develop و Deliver</li><li>في مرحلة Define، أجبر نفسك على تقليص المشكلة إلى جملة واحدة محددة</li><li>في مرحلة Develop، اذكر 3 حلول مختلفة على الأقل، بدلاً من التركيز فقط على أول فكرة تتبادر إلى الذهن</li><li>في مرحلة Deliver، اكتب أصغر نسخة تحقق يمكن تسليمها في غضون أسبوع</li></ol><h2 id="قراءة-إضافية" tabindex="-1">قراءة إضافية <a class="header-anchor" href="#قراءة-إضافية" aria-label="Permalink to “قراءة إضافية”">​</a></h2><p>هذه المقالة تشير أساسًا إلى المواد الرسمية من Design Council حول Double Diamond، وهي مناسبة للمتابعة والقراءة:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{b as __pageData,k as default};
